import numpy as np, json
def transform(g):
    g=[r[:] for r in g]; a=np.array(g); H,W=a.shape
    color=2 if (a==2).any() else None
    cols=np.array(g)
    ys,xs=np.where(a==color)
    r0,r1,c0,c1=ys.min(),ys.max(),xs.min(),xs.max()
    mk=np.where(a>0)
    markers=set(zip(mk[0].tolist(),mk[1].tolist()))
    out=[[0]*W for _ in range(H)]
    for y in range(H):
        for x in range(W):
            if (y,x) in markers: out[y][x]=a[y,x]
    # horizontal: rect rows
    for y in range(r0,r1+1):
        left=not any(m[0]==y and m[1]<c0 for m in markers)
        right=not any(m[0]==y and m[1]>c1 for m in markers)
        if left: 
            for x in range(0,c0):
                if (y,x) not in markers: out[y][x]=color
        if right:
            for x in range(c1+1,W):
                if (y,x) not in markers: out[y][x]=color
    # vertical: rect cols
    for x in range(c0,c1+1):
        up=not any(m[1]==x and m[0]<r0 for m in markers)
        down=not any(m[1]==x and m[0]>r1 for m in markers)
        if up:
            for y in range(0,r0):
                if (y,x) not in markers: out[y][x]=color
        if down:
            for y in range(r1+1,H):
                if (y,x) not in markers: out[y][x]=color
    return out
